{
  "name": "oc-goal",
  "version": "0.1.1",
  "description": "Goal mode (Codex-style thread goals) plugin for opencode",
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    },
    "./src": "./src/index.ts"
  },
  "files": [
    "dist",
    "src"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "goal",
    "goal-mode",
    "codex",
    "agent",
    "ai"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/10xChengTu/oc-goal.git"
  },
  "homepage": "https://github.com/10xChengTu/oc-goal#readme",
  "bugs": "https://github.com/10xChengTu/oc-goal/issues",
  "license": "MIT",
  "author": "10xChengTu <huiz32902@gmail.com>",
  "scripts": {
    "typecheck": "tsc --noEmit",
    "build": "tsc -p tsconfig.build.json",
    "prepublishOnly": "npm run typecheck && npm run build"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.18.3"
  },
  "devDependencies": {
    "@types/node": "^26.1.1",
    "typescript": "^5.5.0"
  }
}
